def run(_context):
    import adsk.core, adsk.fusion
    app = adsk.core.Application.get()
    des = None
    for p in app.activeDocument.products:
        if p.classType()=='adsk::fusion::Design':
            des = adsk.fusion.Design.cast(p)
    body = des.rootComponent.bRepBodies.item(0)
    groups = {'grid_6452': [], 'pin_4064': [], 'bore_6604': [], 'cbore_9652': [], 'bore_7620': []}
    for i in range(body.faces.count):
        f = body.faces.item(i)
        g = f.geometry
        if g.surfaceType != adsk.core.SurfaceTypes.CylinderSurfaceType: continue
        ax = g.axis.asArray()
        if abs(abs(ax[1])-1) > 0.01: continue
        r = round(g.radius*10, 3)
        if r == 3.226: groups['grid_6452'].append(i)
        elif r == 2.032: groups['pin_4064'].append(i)
        elif r == 3.302: groups['bore_6604'].append(i)
        elif r == 4.826: groups['cbore_9652'].append(i)
        elif r == 3.81: groups['bore_7620'].append(i)
    for k,v in groups.items():
        print(k, len(v), v[:6], '...' if len(v)>6 else '')
    return groups

